const raw = $('On Handoff Request').item.json;
const j = { ...raw, ...(raw.triage || {}) };
const rec = $('Load email_events State').first().json || {};
const ef = rec.fields || rec;
const existingDraftId = String(ef.draft_id || '');
const existingTaskId = String(ef.task_id || '');
const existingAlertId = String(ef.alert_id || '');
const reviewRequired = !!j.review_required;
const accepted = !reviewRequired;
const createDraft = accepted && !!j.needs_reply && !existingDraftId;
const createTask = accepted && !!j.needs_task && !existingTaskId;
// Alert only when the AI rating is backed by a deterministic urgency signal (keyword or VIP sender).
const urgentConfig = {
  importance: 'high',
  categories: ['client_request', 'billing'],
  min_confidence: 0.80,
  signals: [
    ['urgent', /\b(urgent|asap|emergency|immediately|critical)\b/],
    ['outage', /\b(outage|offline|(is|are|went|site|server|system|app) down|500 errors?|not working for (all|any) users|blocking)\b/],
    ['deadline', /\b((by|before|due) (today|tonight|eod|end of (the )?day)|(with)?in (an?|one|\d+) hours?)\b/],
    ['billing', /\b(past due|overdue|final notice|payment failed)\b/]
  ]
};
const urgencyText = (String(j.subject || '') + ' ' + String(j.text_body || '')).toLowerCase();
const keywordHit = urgentConfig.signals.find(([, pattern]) => pattern.test(urgencyText));
const urgencySignal = keywordHit ? 'keyword:' + keywordHit[0] : ((j.rules && j.rules.vip) ? 'vip_sender' : '');
const aiUrgent = j.importance === urgentConfig.importance && urgentConfig.categories.includes(j.category) && Number(j.confidence) >= urgentConfig.min_confidence;
const sendAlert = accepted && aiUrgent && !!urgencySignal && !existingAlertId;
const alertReason = sendAlert ? 'ai_high+' + urgencySignal : (existingAlertId ? 'already_alerted' : (!accepted ? 'review_required' : (!aiUrgent ? 'ai_not_urgent' : 'no_urgency_signal')));
return [{ json: {
  ...j,
  existing_draft_id: existingDraftId,
  existing_task_id: existingTaskId,
  existing_alert_id: existingAlertId,
  create_draft: createDraft,
  create_task: createTask,
  send_alert: sendAlert,
  alert_reason: alertReason,
  task_idempotency_key: j.message_id ? 'msg:' + j.message_id : j.idempotency_key
}}];

const plan = $('Prepare Handoff Plan').item.json;
const optionalFirstJson = (name) => {
  try { return $(name).first().json || {}; }
  catch { return {}; }
};
const draft = optionalFirstJson('Create Gmail Draft');
const task = optionalFirstJson('Create Asana Task');
const alert = optionalFirstJson('Urgent Alert Adapter — Not Configured');
const draftId = draft.id || draft.draftId || plan.existing_draft_id || '';
const draftError = draft.error || draft.json?.error || '';
const taskId = task.gid || task.id || task.data || plan.existing_task_id || '';
let taskError = '';
if (plan.create_task && !taskId) taskError = String(task.error || task.json?.error || 'asana_create_failed');
const alertSent = plan.send_alert && !alert.error && !alert.alert_skipped && Object.keys(alert).length > 0;
const alertError = plan.send_alert && alert.error ? String(alert.error) : '';
const alertId = String((alertSent && (alert.id || alert.messageId || alert.ts)) || plan.existing_alert_id || '');
// A Gmail login problem (expired/revoked token, 401/403) breaks drafts and alerts for every email, so flag it separately.
const gmailAuthPattern = /invalid_grant|invalid_client|authorization grant|refresh token|token has been expired or revoked|client authentication failed|invalid credentials|unauthori[sz]ed|\b40[13]\b/i;
const gmailErrorText = [draftError, alertError].filter(Boolean).join(' | ');
const gmailAuthFailed = gmailAuthPattern.test(gmailErrorText);
return [{ json: {
  correlation_id: plan.correlation_id,
  message_id: plan.message_id,
  email_event_id: plan.email_event_id,
  draft_id: draftId,
  draft_error: draftError,
  task_id: taskId,
  task_status: taskError ? 'failed' : (taskId ? 'synced' : 'not_applicable'),
  task_error_code: taskError,
  alert_sent: !!alertSent || !!plan.existing_alert_id,
  alert_id: alertId,
  alert_error: alertError,
  review_required: plan.review_required,
  review_queue_id: plan.review_queue_id || '',
  asana_failed: !!taskError,
  gmail_auth_failed: gmailAuthFailed,
  gmail_auth_error: gmailAuthFailed ? gmailErrorText.slice(0, 500) : ''
} }];
